style.css:
@-moz-document domain("netflix.com") {
:root {
    -rosa-fondo: #fde2ec;
    -rosa-claro: #fff1f6;
    -rosa-medio: #f4a7c1;
    -texto-principal: #4a2c3a;
    -texto-secundario: #6b3f52;
    -blanco-suave: #fff8fb;
  }

  /* Fondo general con GIF */
  body {
    background:
   linear-gradient(
    rgba(255, 255, 255, 0.75),
    rgba(255, 255, 255, 0.75)
  ),
    url("https://i.imgur.com/NYMRhzp.gif") !important;
      background-size: cover !important;
      background-repeat: no-repeat !important;
      background-position: center center !important;
      background-attachment: fixed !important;

    
    color: var(--texto-principal) !important;
  }

  /* Barra superior */
  .netflix-sans-font-loaded .pinning-header {
    background-color: rgba(253, 226, 236, 0.85) !important;
    backdrop-filter: blur(10px);
  }

  /* Texto */
  h1, h2, h3, h4, h5, p, span, a {
    color: var(--texto-principal) !important;
  }

  /* Títulos */
  .title-name,
  .fallback-text {
    text-shadow: 0 1px 2px rgba(255, 255, 255, 0.7);
  }

  /* Tarjetas */
  .slider-item,
  .title-card-container {
    border-radius: 18px !important;
    overflow: hidden;
  }

  /* Hover cute */
  .slider-item:hover {
    transform: scale(1.04);
    box-shadow: 0 10px 30px rgba(244, 167, 193, 0.6) !important;
    transition: all 0.25s ease;
  }

  /* Botones */
  button,
  .nf-flat-button {
    background-color: var(--rosa-medio) !important;
    color: white !important;
    border-radius: 999px !important;
    border: none !important;
  }

  button:hover {
    background-color: #ec8fb0 !important;
  }

  /* Descripciones */
  .previewModal--detailsSynopsis,
  .previewModal--detailsMetadata {
    color: var(--texto-secundario) !important;
  }

  /* Quitar negro fuerte */
  .previewModal--wrapper,
  .previewModal--player_container {
    background-color: var(--blanco-suave) !important;
  }
}
